-- 060_uc004_demo_pending.sql
-- Suhaila / UC-004 demo data: EIGHT pending-approval pay periods, each with three
-- calculated employees, so the Approvals page always has real payrolls waiting for a
-- live approve/reject during the demo. Loads automatically via `npm run seed`.
--
-- Safe & isolated:
--   * Uses its own unique IDs (5ada...) so it never touches UC-003 / UC-005 demo data.
--   * Runs LAST (file name 060...) so nothing overwrites the pending status.
--   * Idempotent: re-running `npm run seed` re-arms all eight back to pending_approval,
--     which is handy for re-rehearsing after you approve/reject during practice.
--   * Reuses existing staff (Andrea Chua, etc.), rate set, and manager user already seeded.
--
-- Eight periods give plenty of cushion to rehearse the approve/reject flow many times
-- before needing to re-seed.

-- 1) Eight pay periods, all pending_approval, recent dates so they sort to the top.
INSERT INTO pay_period (id, start_date, end_date, status, total_gross, total_net)
